import abc

import six
from moler.cmd.unix.genericunix import GenericUnixCommand

__author__ = "Marcin Usielski"
__copyright__ = "Copyright (C) 2023-2024, Nokia"
__email__ = "marcin.usielski@nokia.com"


@six.add_metaclass(abc.ABCMeta)
class GenericPositionerEC(GenericUnixCommand):
    """Generic Positioner EC command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Create positioner EC commands.

        :param connection: Moler connection to device, terminal when command is executed.
        :param prompt: prompt (on system where command runs).
        :param newline_chars: Characters to split lines - list.
        :param runner: Runner to run command.
        """
        super(GenericPositionerEC, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.add_failure_indication(r"Traceback \(most recent call last\)")
